namespace rac1::oracle {

namespace {

uint32_t f2u(float f) { uint32_t u; std::memcpy(&u, &f, 4); return u; }
float u2f(uint32_t u) { float f; std::memcpy(&f, &u, 4); return f; }
bool eqv(const VUVector& x, const VUVector& y) { return std::memcmp(&x, &y, 16) == 0; }

// What differs between the interpreter's run `ra` / state `a` and the port's `rb` / `b` (empty: nothing).
std::string diff(const VUState& a, const VUState& b, const VuMicroRun& ra, const VuMicroRun& rb, bool with_mem) {
    char buf[200];
    std::string d;
    auto add = [&](const char* s) { d += s; d += ' '; };
    for (int r = 0; r < 32; ++r)
        if (!eqv(a.vf[static_cast<size_t>(r)], b.vf[static_cast<size_t>(r)])) {
            std::snprintf(buf, sizeof buf, "vf%d(%08x %08x %08x %08x / %08x %08x %08x %08x)", r, a.vf[r].u[0], a.vf[r].u[1], a.vf[r].u[2], a.vf[r].u[3], b.vf[r].u[0], b.vf[r].u[1],
                          b.vf[r].u[2], b.vf[r].u[3]);
            add(buf);
        }
    for (int r = 0; r < 16; ++r)
        if (a.vi[r] != b.vi[r]) {
            std::snprintf(buf, sizeof buf, "vi%d(%d/%d)", r, a.vi[r], b.vi[r]);
            add(buf);
        }
    if (!eqv(a.acc, b.acc)) add("acc");
    if (f2u(a.q) != f2u(b.q)) {
        std::snprintf(buf, sizeof buf, "q(%08x/%08x)", f2u(a.q), f2u(b.q));
        add(buf);
    }
    if (f2u(a.i) != f2u(b.i)) add("i");
    if (a.macflag != b.macflag) {
        std::snprintf(buf, sizeof buf, "mac(%04x/%04x)", a.macflag, b.macflag);
        add(buf);
    }
    if (a.statusflag != b.statusflag) {
        std::snprintf(buf, sizeof buf, "status(%03x/%03x)", a.statusflag, b.statusflag);
        add(buf);
    }
    if (a.clipflag != b.clipflag) {
        std::snprintf(buf, sizeof buf, "clip(%06x/%06x)", a.clipflag, b.clipflag);
        add(buf);
    }
    if (with_mem && a.mem != b.mem) add("mem");
    const VuPipe &pa = ra.pipe(), &pb = rb.pipe();
    if (pa.pc != pb.pc) {
        std::snprintf(buf, sizeof buf, "pc(%03x/%03x)", pa.pc, pb.pc);
        add(buf);
    }
    if (pa.issued != pb.issued) add("issued");
    if (pa.halted != pb.halted) add("halted");
    if (pa.branch_pending != pb.branch_pending || (pa.branch_pending && pa.branch_target != pb.branch_target)) add("branch");
    if (pa.q_pending != pb.q_pending || (pa.q_pending && (f2u(pa.q_next) != f2u(pb.q_next) || pa.q_ready != pb.q_ready))) add("q-in-flight");
    if (pa.kick_delay != pb.kick_delay || (pa.kick_delay != 0 && pa.kick_addr != pb.kick_addr)) add("kick-pending");
    if (pa.halt_pending != pb.halt_pending || (pa.halt_pending && pa.halt_delay != pb.halt_delay)) add("halt-pending");
    return d;
}

using Packets = std::vector<std::vector<uint8_t>>;
std::function<void(uint32_t)> tap(VUState& st, Packets& out) {
    return [&st, &out](uint32_t addr) {
        const uint32_t qwc = vu1::gif_packet_qwc(st, addr);
        std::vector<uint8_t> pkt(static_cast<size_t>(qwc) * 16 + 4);
        std::memcpy(pkt.data(), &addr, 4);
        for (uint32_t q = 0; q < qwc; ++q) std::memcpy(&pkt[4 + q * 16], &st.mem[((addr + q) & 0x3ff) << 4], 16);
        out.push_back(std::move(pkt));
    };
}

struct RunResult {
    bool same = true;
    uint64_t steps = 0;
    int calls = 0;
    int single = 0;  // calls that ran one instruction (the exact step function took over)
    int kicks = 0;
    std::string why;
};
std::vector<uint8_t> g_cover;  // the micro addresses the interpreter ran in the cases of the current program

// One program run, the interpreter against the port, compared after each call of the port (the interpreter
// having run as many instructions as the port reports).
RunResult run_pair(VUState& a, VUState& b, const uint64_t* micro, size_t size, uint32_t start, VuNativeStep port, uint64_t limit, Packets* ka, Packets* kb, bool mem_often) {
    if (g_cover.size() < size) g_cover.assign(size, 0);
    RunResult res;
    VuMicroRun ra, rb;
    ra.start(a, micro, size, start);
    ra.set_pc_mask(0x7ff);  // (VU1: branch targets wrap in the 2048-instruction micro memory; the generated ports mask them)
    rb.start(b, micro, size, start, port);
    rb.limit_issue(limit);
    for (;;) {
        if (rb.pipe().issued >= limit) break;  // (the caller's instruction budget: the port stops exactly there)
        const uint32_t pc_before = rb.pc();
        const bool gb = rb.step();
        ++res.calls;
        const uint64_t n = rb.pipe().issued - ra.pipe().issued;
        bool ga = true;
        for (uint64_t k = 0; k < n && ga; ++k) {
            if (ra.pipe().halted || ra.pc() >= size) {
                ga = false;
                break;
            }
            g_cover[ra.pc()] = 1;
            ga = ra.step();
            if (!ga && k + 1 < n) {
                res.same = false;
                res.why = "interpreter ended early";
                return res;
            }
        }
        if (n == 0) ga = ra.step();
        res.steps += n;
        if (n == 1) ++res.single;
        std::string d = diff(a, b, ra, rb, mem_often || res.calls % 64 == 0 || !gb);  // (the exact ports run one instruction per call: the 16 KB memory compared every 64th)
        if (ka != nullptr && (ka->size() != kb->size() || (!ka->empty() && ka->back() != kb->back()))) d += "kicks ";  // (all of them compared at the end)
        if (ga != gb) d += "end ";
        if (!d.empty()) {
            res.same = false;
            char at[80];
            std::snprintf(at, sizeof at, "after %llu instructions (call from pc %03x to %03x): ", static_cast<unsigned long long>(res.steps), pc_before, rb.pc());
            res.why = at + d;
            return res;
        }
        if (!gb) break;
    }
    ra.finish();
    rb.finish();
    std::string d = diff(a, b, ra, rb, true);
    if (ka != nullptr && *ka != *kb) d += "kicks ";
    if (!d.empty()) {
        res.same = false;
        res.why = "at the end: " + d;
    }
    if (ka != nullptr) res.kicks = static_cast<int>(ka->size());
    return res;
}

struct State {
    std::string path;
    uint32_t start = 0;
    VUState st{};
    int prog = -1;  // index into world_vu1_programs()
};

}  // namespace

void batch_104() {
    if (g_only_batch != 104) return;
    g_batch = 104;
    int nprog = 0;
    const WorldVu1Program* progs = world_vu1_programs(nprog);
    const char* only_env = std::getenv("ORACLE_WORLD_PROGRAM");
    const char* only = std::getenv("ORACLE_ONLY");
    // ---- the captured start states, by program
    const char* dir_env = std::getenv("ORACLE_VU1_DIR");
    const std::string dirs = dir_env != nullptr ? std::string(dir_env) : dump_path("vu1_world");
    std::vector<std::string> files;
    for (size_t at = 0; at <= dirs.size();) {
        size_t end = dirs.find(':', at);
        if (end == std::string::npos) end = dirs.size();
        const std::string d = dirs.substr(at, end - at);
        at = end + 1;
        if (std::filesystem::is_directory(d))
            for (const auto& de : std::filesystem::recursive_directory_iterator(d))
                if (de.path().extension() == ".bin" && de.path().filename().string().rfind("vu1w_", 0) == 0) files.push_back(de.path().string());
    }
    std::sort(files.begin(), files.end());
    if (files.empty()) {  // no captures at all (not recorded on this machine): the batch is skipped, not failed
        std::printf("batch 104: skipped (no captured VU1 states in %s: run rac1-native with RAC1_VU1_CAPTURE=<dir> RAC1_VU1_CAPTURE_ALL=12, "
                    "this batch's header)\n", dirs.c_str());
        ++g_skipped;
        return;
    }
    std::vector<std::vector<State>> by_prog(static_cast<size_t>(nprog));
    std::vector<std::shared_ptr<std::array<uint64_t, 2048>>> micros;  // (the micro memory of each distinct image)
    std::map<std::string, size_t> micro_of;
    for (const std::string& path : files) {
        FILE* fp = std::fopen(path.c_str(), "rb");
        if (fp == nullptr) continue;
        uint32_t hdr[4];
        State s;
        float fr[4];
        uint32_t fl[4];
        auto micro = std::make_shared<std::array<uint64_t, 2048>>();
        bool rd = std::fread(hdr, 4, 4, fp) == 4 && std::fread(s.st.vf.data(), sizeof(VUVector), 32, fp) == 32 &&
                  std::fread(s.st.vi.data(), 2, 16, fp) == 16 && std::fread(&s.st.acc, sizeof(VUVector), 1, fp) == 1 &&
                  std::fread(fr, 4, 4, fp) == 4 && std::fread(fl, 4, 4, fp) == 4 &&
                  std::fread(s.st.mem.data(), 1, s.st.mem.size(), fp) == s.st.mem.size() && std::fread(micro->data(), 8, 2048, fp) == 2048;
        std::fclose(fp);
        if (!rd || hdr[0] != 0x31555676u) continue;
        s.st.q = fr[0], s.st.i = fr[1], s.st.r = fr[2], s.st.p = fr[3];
        s.st.macflag = fl[0], s.st.statusflag = fl[1], s.st.clipflag = fl[2];
        s.st.xtop = hdr[2];
        s.start = hdr[1];
        s.path = path;
        int found = -1;
        for (int p = 0; p < nprog && found < 0; ++p)
            if (s.start < progs[p].n && vu1::code_hash(micro->data(), progs[p].n) == progs[p].hash) found = p;
        if (found < 0) continue;  // (another pass's programs)
        s.prog = found;
        // one micro memory per program: the first 'n' instructions are the program (the rest is stale code of other sets and is not run)
        std::string key = std::to_string(found);
        if (micro_of.find(key) == micro_of.end()) {
            micro_of[key] = micros.size();
            micros.push_back(micro);
        }
        by_prog[static_cast<size_t>(found)].push_back(std::move(s));
    }
    // ORACLE_WORLD_DIGEST=<dir>[:<dir>..]: every captured state of the directories (vu1_*.bin of any program: the micro memory comes from
    // the file) run by the interpreter; one line per state with a digest of its kicked packets and of its final registers / memory, then the
    // total (testing the interpreter's integer branch hazard, RAC1_VU_HZ: the digests under two settings are compared by diff)
    if (const char* dg = std::getenv("ORACLE_WORLD_DIGEST")) {
        std::vector<std::string> fl;
        const std::string all = dg;
        for (size_t at = 0; at <= all.size();) {
            size_t end = all.find(':', at);
            if (end == std::string::npos) end = all.size();
            const std::string d = all.substr(at, end - at);
            at = end + 1;
            if (std::filesystem::is_directory(d))
                for (const auto& de : std::filesystem::recursive_directory_iterator(d))
                    if (de.path().extension() == ".bin") fl.push_back(de.path().string());
        }
        std::sort(fl.begin(), fl.end());
        auto mix = [](uint64_t h, const void* p, size_t n) {
            const uint8_t* b = static_cast<const uint8_t*>(p);
            for (size_t i = 0; i < n; ++i) h = (h ^ b[i]) * 0x100000001b3ull;
            return h;
        };
        uint64_t total = 0xcbf29ce484222325ull;
        for (const std::string& path : fl) {
            FILE* fp = std::fopen(path.c_str(), "rb");
            if (fp == nullptr) continue;
            uint32_t hdr[4];
            auto st = std::make_unique<VUState>();
            float fr[4];
            uint32_t flg[4];
            auto micro = std::make_unique<std::array<uint64_t, 2048>>();
            bool rd = std::fread(hdr, 4, 4, fp) == 4 && std::fread(st->vf.data(), sizeof(VUVector), 32, fp) == 32 && std::fread(st->vi.data(), 2, 16, fp) == 16 &&
                      std::fread(&st->acc, sizeof(VUVector), 1, fp) == 1 && std::fread(fr, 4, 4, fp) == 4 && std::fread(flg, 4, 4, fp) == 4 &&
                      std::fread(st->mem.data(), 1, st->mem.size(), fp) == st->mem.size() && std::fread(micro->data(), 8, 2048, fp) == 2048;
            std::fclose(fp);
            if (!rd || hdr[0] != 0x31555676u) continue;
            st->q = fr[0], st->i = fr[1], st->r = fr[2], st->p = fr[3];
            st->macflag = flg[0], st->statusflag = flg[1], st->clipflag = flg[2];
            st->xtop = hdr[2];
            uint64_t h = 0xcbf29ce484222325ull;
            int kicks = 0;
            VUState& a = *st;
            a.xgkick_hook = [&](uint32_t addr) {
                const uint32_t qwc = vu1::gif_packet_qwc(a, addr);
                for (uint32_t q = 0; q < qwc; ++q) h = mix(h, &a.mem[((addr + q) & 0x3ff) << 4], 16);
                ++kicks;
            };
            VuMicroRun ra;
            ra.start(a, micro->data(), 2048, hdr[1]);
            ra.set_pc_mask(0x7ff);
            uint64_t n = 0;
            while (n < 400000 && ra.step()) ++n;
            ra.finish();
            h = mix(h, a.vf.data(), sizeof(a.vf));
            h = mix(h, a.vi.data(), sizeof(a.vi));
            h = mix(h, a.mem.data(), a.mem.size());
            total ^= h + 0x9e3779b97f4a7c15ull + (total << 6) + (total >> 2);
            std::printf("%s %016llx kicks %d steps %llu\n", path.c_str(), static_cast<unsigned long long>(h), kicks, static_cast<unsigned long long>(n));
        }
        std::printf("digest total %016llx\n", static_cast<unsigned long long>(total));
        return;
    }
    // ORACLE_WORLD_SCAN=1: each captured state run by the interpreter, its kicked packets checked for plausible vertices (ST finite, XY inside the
    // 4096 x 4096 window around the offset): the states that kick garbage are listed (no checks of the ports)
    if (std::getenv("ORACLE_WORLD_SCAN") != nullptr) {
        int shown = 0, bad_states = 0, total = 0;
        for (int p = 0; p < nprog; ++p)
            for (const State& s : by_prog[static_cast<size_t>(p)]) {
                if (only_env != nullptr && std::string(only_env) != progs[p].name) continue;
                VUState a = s.st;
                std::string why;
                a.xgkick_hook = [&](uint32_t addr) {
                    const uint32_t qwc = vu1::gif_packet_qwc(a, addr);
                    uint32_t i = 0;
                    while (i < qwc && why.empty()) {
                        uint64_t lo, hi;
                        std::memcpy(&lo, &a.mem[((addr + i) & 0x3ff) << 4], 8);
                        std::memcpy(&hi, &a.mem[((addr + i) & 0x3ff) << 4] + 8, 8);
                        const uint32_t nloop = lo & 0x7fff, flg = (lo >> 58) & 3, nreg = ((lo >> 60) & 15) == 0 ? 16 : (lo >> 60) & 15;
                        ++i;
                        if (flg != 0) break;
                        for (uint32_t n = 0; n < nloop && why.empty(); ++n)
                            for (uint32_t r = 0; r < nreg && why.empty(); ++r, ++i) {
                                if (i >= qwc) { why = "tag data past the packet"; break; }
                                const uint8_t* q = &a.mem[((addr + i) & 0x3ff) << 4];
                                uint32_t w[4];
                                std::memcpy(w, q, 16);
                                const uint32_t reg = (hi >> (4 * r)) & 15;
                                if (reg == 2 && (std::isnan(u2f(w[0])) || std::isnan(u2f(w[1])) || std::fabs(u2f(w[0])) > 1e6f)) why = "bad ST";
                                if (reg == 4 && std::getenv("ORACLE_WORLD_SCAN_XY") != nullptr && ((w[0] & 0xffff) < 0x4000 || (w[0] & 0xffff) > 0xc000 || (w[1] & 0xffff) < 0x4000 || (w[1] & 0xffff) > 0xc000)) why = "XY outside the window";
                            }
                    }
                };
                VuMicroRun ra;
                ra.start(a, micros[micro_of[std::to_string(p)]]->data(), 2048, s.start);
                ra.set_pc_mask(0x7ff);
                for (int n = 0; n < 400000; ++n)
                    if (!ra.step()) break;
                ra.finish();
                ++total;
                if (!why.empty()) {
                    ++bad_states;
                    if (shown++ < 12) std::printf("  scan %s %s start %03x: %s\n", progs[p].name, s.path.c_str(), s.start, why.c_str());
                }
            }
        std::printf("scan: %d / %d captured states kick implausible vertices\n", bad_states, total);
        return;
    }
    // ORACLE_WORLD_TRACE=<state file>: the interpreter's run of one captured state (pc and the integer registers after each
    // instruction, the kicks) on stdout, for finding out what a program does (no checks)
    if (const char* tr = std::getenv("ORACLE_WORLD_TRACE")) {
        for (int p = 0; p < nprog; ++p)
            for (const State& s : by_prog[static_cast<size_t>(p)])
                if (s.path == tr) {
                    VUState a = s.st;
                    a.xgkick_hook = [&](uint32_t addr) {
                        const uint32_t qwc = vu1::gif_packet_qwc(a, addr);
                        std::printf("KICK %03x qwc %u\n", addr, qwc);
                        if (const char* pk = std::getenv("ORACLE_WORLD_TRACE_PKT")) {  // (the packet's bytes, appended to a file)
                            if (FILE* f = std::fopen(pk, "ab")) {
                                for (uint32_t q = 0; q < qwc; ++q) std::fwrite(&a.mem[((addr + q) & 0x3ff) << 4], 1, 16, f);
                                std::fclose(f);
                            }
                        }
                    };
                    VuMicroRun ra;
                    ra.start(a, micros[micro_of[std::to_string(p)]]->data(), 2048, s.start);
                    ra.set_pc_mask(0x7ff);
                    for (int n = 0; n < 200000; ++n) {
                        const uint32_t pc = ra.pc();
                        const bool g = ra.step();
                        std::printf("%06d pc %03x vi", n, pc);
                        for (int r = 1; r < 16; ++r) std::printf(" %d", a.vi[r]);
                        std::printf("\n");
                        if (!g) break;
                    }
                    ra.finish();
                    std::printf("program %s done\n", progs[p].name);
                    return;
                }
        std::printf("trace: state %s not found\n", tr);
        return;
    }
    // the jump table at the start of each program: the addresses of the `b` instructions among its first 32 (entries by an MSCAL)
    std::vector<std::vector<uint32_t>> entries(static_cast<size_t>(nprog));
    for (int p = 0; p < nprog; ++p) {
        const auto& m = *micros[micro_of[std::to_string(p)]];
        for (uint32_t pc = 0; pc < 32 && pc < progs[p].n; ++pc) {
            const uint32_t lo = static_cast<uint32_t>(m[pc]), up = static_cast<uint32_t>(m[pc] >> 32);
            if ((up & 0x80000000u) == 0 && (lo & 0x80000000u) == 0 && ((lo >> 25) & 0x7f) == 0x20) entries[static_cast<size_t>(p)].push_back(pc);
        }
    }
    const int variants = std::getenv("ORACLE_VU1_VARIANTS") != nullptr ? std::atoi(std::getenv("ORACLE_VU1_VARIANTS")) : 4;
    auto perturb = [&](VUState& a, int variant) {
        if (variant >= 4) {  // a wild start: the integer registers and some memory words small integers, the control flow explored (the budget cuts the run)
            for (int r = 1; r < 16; ++r)
                if (ri(0, 1) == 0) a.vi[static_cast<size_t>(r)] = static_cast<int16_t>(ri(0, 2) == 0 ? ri(-2, 0x3ff) : ri(0, 6));
            for (size_t k = 0; k < a.mem.size(); k += 4)
                if (ri(0, 5) == 0) {
                    const uint32_t w = static_cast<uint32_t>(ri(0, 24));
                    std::memcpy(&a.mem[k], &w, 4);
                }
            for (int r = 1; r < 32; ++r)
                for (int l = 0; l < 4; ++l)
                    if (ri(0, 3) == 0) a.vf[static_cast<size_t>(r)].f[l] = ri(0, 4) == 0 ? u2f(R()) : rf(-50, 50);
        } else if (variant != 0) {
            for (int r = 1; r < 32; ++r)
                for (int l = 0; l < 4; ++l)
                    if (ri(0, 3) == 0) a.vf[static_cast<size_t>(r)].f[l] = rf(-50, 50);
            for (size_t k = 0; k < a.mem.size(); k += 4) {
                uint32_t w;
                std::memcpy(&w, &a.mem[k], 4);
                const uint32_t e = (w >> 23) & 0xff;
                if (e > 0x60 && e < 0x9f && ri(0, 2) == 0) {  // a float: moved by up to +-25% (x2 for the clip tests)
                    float f = u2f(w) * rf(variant % 4 == 3 ? -1.0f : 0.75f, variant % 4 == 3 ? 2.0f : 1.25f);
                    std::memcpy(&a.mem[k], &f, 4);
                }
            }
        }
    };
    const size_t max_per_prog = std::getenv("ORACLE_WORLD_MAX") != nullptr ? static_cast<size_t>(std::atoi(std::getenv("ORACLE_WORLD_MAX"))) : 100000;
    for (const char* kind : {"exact", "fast"}) {
        const std::string test = std::string("world_vu1_") + kind;
        if (only != nullptr && std::string(only) != test) continue;
        const bool fast = std::string(kind) == "fast";
        int tot_cases = 0, tot_ok = 0;
        uint64_t tot_steps = 0;
        int tot_kicks = 0, tot_single = 0;
        for (int p = 0; p < nprog; ++p) {
            if (only_env != nullptr && std::string(only_env) != progs[p].name) continue;
            const auto& states = by_prog[static_cast<size_t>(p)];
            const auto& micro = *micros[micro_of[std::to_string(p)]];
            g_cover.assign(progs[p].n, 0);
            int cases = 0, ok = 0, shown = 0;
            uint64_t steps = 0;
            int kicks = 0, single = 0;
            std::map<uint32_t, int> starts;
            for (size_t si = 0; si < states.size() && si < max_per_prog; ++si) {
                const State& s = states[si];
                ++starts[s.start];
                for (int variant = 0; variant < (fast ? variants : std::min(variants, 2)); ++variant) {
                    // variant 2: another entry of the program's jump table (the `b` slots at its start: entries the game's captured runs never start at),
                    // from the same captured state
                    uint32_t start = s.start;
                    if (variant == 2 && !entries[static_cast<size_t>(p)].empty()) start = entries[static_cast<size_t>(p)][static_cast<size_t>(ri(0, static_cast<int>(entries[static_cast<size_t>(p)].size()) - 1))];
                    VUState a = s.st;
                    perturb(a, variant);
                    VUState b = a;
                    Packets ka, kb;
                    a.xgkick_hook = tap(a, ka);
                    b.xgkick_hook = tap(b, kb);
                    uint64_t budget = variant >= 4 ? static_cast<uint64_t>(ri(200, 30000)) : (variant % 2 == 1 && ri(0, 2) == 0) ? static_cast<uint64_t>(ri(1, 6000)) : 2000000;
                    if (!fast) budget = std::min<uint64_t>(budget, 400000);
                    // (exact: one instruction per call, the whole state compared after each; fast: after each call)
                    const RunResult r = run_pair(a, b, micro.data(), progs[p].n, start, fast ? progs[p].fast : progs[p].exact, budget, &ka, &kb, fast);
                    steps += r.steps;
                    single += r.single;
                    kicks += r.kicks;
                    ++cases;
                    if (r.same) ++ok;
                    else if (shown++ < 4) std::printf("  %s %s: %s variant %d (start %03x): %s\n", test.c_str(), progs[p].name, s.path.c_str(), variant, start, r.why.c_str());
                }
            }
            char what[64];
            std::snprintf(what, sizeof what, "%s %s", test.c_str(), progs[p].name);
            if (cases == 0) {
                std::printf("%-30s %s  FAIL (no captured states: run rac1-native with RAC1_VU1_CAPTURE=<dir> RAC1_VU1_CAPTURE_ALL=12 under assets/dumps/oracle/vu1_world)\n", what, "0x001xxxxx");
                ++g_fail;
                continue;
            }
            uint32_t covered = 0;
            std::string miss;
            for (uint32_t pc = 0; pc < progs[p].n; ++pc) {
                if (g_cover[pc] != 0) ++covered;
                else if (std::getenv("ORACLE_COVER") != nullptr) {
                    char b[16];
                    std::snprintf(b, sizeof b, " %x", pc);
                    miss += b;
                }
            }
            std::string st;
            for (const auto& kv : starts) {
                char b[24];
                std::snprintf(b, sizeof b, "%s%x:%d", st.empty() ? "" : " ", kv.first, kv.second);
                st += b;
            }
            std::printf("%-30s %s  %s (%d/%d cases, %llu instructions, %d kicks; coverage %u / %u; start states %s)%s%s\n", what, "(ELF data)", ok == cases ? "ok" : "FAIL", ok, cases,
                        static_cast<unsigned long long>(steps), kicks, covered, progs[p].n, st.c_str(), miss.empty() ? "" : " not run:", miss.c_str());
            tot_cases += cases;
            tot_ok += ok;
            tot_steps += steps;
            tot_kicks += kicks;
            tot_single += single;
            if (ok != cases) ++g_fail;
        }
        std::printf("%-30s total %d/%d cases, %llu instructions, %d kicks (%d single steps)\n", test.c_str(), tot_ok, tot_cases, static_cast<unsigned long long>(tot_steps), tot_kicks, tot_single);
    }
}

}  // namespace rac1::oracle
